const normalizeMsisdnEgypt = (raw?: string): string => {
  try {
    const s = String(raw || '').replace(/[^0-9+]/g, '');
    if (!s) return '';
    if (s.startsWith('+20')) {
      const rest = s.slice(3);
      return rest.startsWith('1') ? '0' + rest : rest;
    }
    if (s.startsWith('0020')) {
      const rest = s.slice(4);
      return rest.startsWith('1') ? '0' + rest : rest;
    }
    if (s.startsWith('20')) {
      const rest = s.slice(2);
      return rest.startsWith('1') ? '0' + rest : rest;
    }
    if (s.startsWith('0')) return s;
    if (/^(10|11|12|15)/.test(s)) return '0' + s;
    return s;
  } catch { return ''; }
};

/** مفتاح موحّد للتفريق بين المعاملات وتفادي التكرار (نفس الاستعلام والواجهة). */
function getTransactionKey(t: any): string {
  const ref = String((t as any)?.reference || (t as any)?.transactionReference || (t as any)?.receipt?.reference || '').trim();
  const txnId = String((t as any)?.transactionId || '').trim();
  const id = String((t as any)?.id || '').trim();
  const createdAtMs = new Date(((t as any)?.createdAt || 0)).getTime();
  const canonical = ref || txnId;
  if (canonical) return `tx:${canonical}`;
  if (id) return `id:${id}`;
  return `t:${createdAtMs}`;
}

function mergeTransactionListsByDedupKey(primary: any[], secondary: any[]) {
  const mergedByKey = new Map<string, any>();
  for (const t of primary) {
    const k = getTransactionKey(t);
    if (k) mergedByKey.set(k, t);
  }
  for (const t of secondary) {
    const k = getTransactionKey(t);
    if (k && !mergedByKey.has(k)) mergedByKey.set(k, t);
  }
  return Array.from(mergedByKey.values());
}

/** معرفات حذف نهائي (permanent) لا تُعاد من getDeletedTransactionsByUser لأنه يستبعد permanent — نخزّنها ونفلتر بها الدمج من localStorage */
function getPermanentDeletedIdsStorageKey(uid: string | undefined, shopId: string): string {
  const sid = shopId || 'main';
  return `permanentDeletedTransactionIds_${uid || 'default'}_${sid}`;
}

function readPermanentDeletedIdsFromLS(uid: string | undefined, shopId: string): string[] {
  try {
    const raw = localStorage.getItem(getPermanentDeletedIdsStorageKey(uid, shopId));
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.map((x: any) => String(x)).filter(Boolean) : [];
  } catch {
    return [];
  }
}

function addPermanentDeletedIdsToLS(uid: string | undefined, shopId: string, ids: string[]): void {
  if (!uid) return;
  const set = new Set(readPermanentDeletedIdsFromLS(uid, shopId));
  ids.forEach((id) => {
    const s = String(id || '').trim();
    if (s) set.add(s);
  });
  try {
    localStorage.setItem(getPermanentDeletedIdsStorageKey(uid, shopId), JSON.stringify([...set]));
  } catch {
    /* ignore */
  }
}

function stripTransactionFromTransactionsLocalStorageKeys(uid: string | undefined, shopId: string, transactionId: string): void {
  const keysToTry = new Set<string>([
    `transactions_${uid || 'default'}_${shopId || 'main'}`,
    `transactions_${uid || 'default'}_main`,
  ]);
  if (uid) {
    try {
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith(`transactions_${uid}_`) && !k.endsWith('_lastUpdated')) keysToTry.add(k);
      }
    } catch {
      /* ignore */
    }
  }
  const tid = String(transactionId || '');
  for (const k of keysToTry) {
    try {
      const raw = localStorage.getItem(k);
      if (!raw) continue;
      const parsed = JSON.parse(raw) as any[];
      if (!Array.isArray(parsed)) continue;
      const filtered = parsed.filter((tx: any) => String(tx?.id || '') !== tid);
      localStorage.setItem(k, JSON.stringify(filtered));
    } catch {
      /* ignore */
    }
  }
}

function buildDeletedIdsSet(
  deletedList: any[] | undefined,
  uid: string | undefined,
  shopId: string,
  extraPermanentFromFirestore?: Set<string>
): Set<string> {
  const ids = new Set<string>();
  (deletedList || []).forEach((dt: any) => {
    const a = String(dt?.id || '');
    const b = String(dt?.originalTransactionId || '');
    if (a) ids.add(a);
    if (b) ids.add(b);
  });
  readPermanentDeletedIdsFromLS(uid, shopId).forEach((id) => ids.add(id));
  extraPermanentFromFirestore?.forEach((id) => ids.add(id));
  return ids;
}

function isTransactionHiddenByDeletedIds(t: any, deletedIds: Set<string>): boolean {
  const id = String(t?.id || '');
  if (id && deletedIds.has(id)) return true;
  const txId = String((t as any)?.transactionId || '').trim();
  if (txId && deletedIds.has(txId)) return true;
  const ref = String((t as any)?.reference || (t as any)?.transactionReference || (t as any)?.receipt?.reference || '').trim();
  if (ref && deletedIds.has(ref)) return true;
  return false;
}

