  // حالة نافذة بيانات المبيعات
  const [isSalesDataOpen, setIsSalesDataOpen] = useState(false);
  const [pendingBarcode, setPendingBarcode] = useState<string | null>(null);
  const barcodeBufferRef = React.useRef<string>('');
  const lastKeyTimeRef = React.useRef<number>(0);

  // فتح نافذة المبيعات تلقائياً عند مسح باركود خارجها
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (isSalesDataOpen) return;
      // تجنّب التقاط Enter أثناء الكتابة داخل أي حقول إدخال/نموذج
      try {
        const active = document.activeElement as HTMLElement | null;
        if (active) {
          const tag = active.tagName?.toLowerCase();
          const isTyping = (
            tag === 'input' ||
            tag === 'textarea' ||
            tag === 'select' ||
            tag === 'button' ||
            active.isContentEditable === true
          );
          if (isTyping) return;
        }
      } catch { }
      const now = Date.now();
      if (e.key === 'Enter') {
        const code = (barcodeBufferRef.current || '').trim();
        barcodeBufferRef.current = '';
        if (code) {
          // منع فتح النافذة للأرقام القصيرة (مثل 1-9) لتجنب الفتح بالخطأ
          if (code.length < 2 && /^\d+$/.test(code)) {
             return;
          }
          setPendingBarcode(code);
          setIsSalesDataOpen(true);
        }
        return;
      }
      if (e.key.length === 1) {
        if (now - (lastKeyTimeRef.current || 0) > 100) {
          barcodeBufferRef.current = '';
        }
        barcodeBufferRef.current += e.key;
        lastKeyTimeRef.current = now;
      }
    };
    window.addEventListener('keydown', handler as unknown as EventListener);
    return () => window.removeEventListener('keydown', handler as unknown as EventListener);
  }, [isSalesDataOpen]);
  const [isWalletManagementOpen, setIsWalletManagementOpen] = useState(false);
  const [walletManagementAutoAdd, setWalletManagementAutoAdd] = useState(false);
  const [isWalletsListOpen, setIsWalletsListOpen] = useState(false);
