  // Listen for external updates (e.g. from popup transactions) to update balances immediately
  useEffect(() => {
    const handleExternalUpdate = (event: any) => {
      const { cashBalance: newCash, walletBalances: newWallets, newTransaction, limitUpdate, delta } = event.detail || {};
      
      // حفظ لقطة كاملة قبل تطبيق آخر معاملة قادمة من السيرفر لاستخدامها في "تصحيح آخر عملية"
      if (newTransaction) {
        try {
          const snapshot = {
            txId: String((newTransaction as any).id || ''),
            txReference: String((newTransaction as any).reference || (newTransaction as any).transactionId || ''),
            cashBalance,
            walletBalances: { ...walletBalances },
            selectedWalletLimits: selectedWalletLimits ? { ...selectedWalletLimits } : null,
          };
          lastTxSnapshotRef.current = snapshot;
          if (user?.uid) {
            const key = `undo_last_tx_snapshot_${user.uid}`;
            localStorage.setItem(key, JSON.stringify(snapshot));
          }
        } catch (e) {
          console.warn('Failed to save undo snapshot for last transaction:', e);
        }
      }

      // إن وُجدت أرصدة مطلقة مع delta (مثلاً مودم SMS) لا نطبّق delta على النقدية/المحفظة — الـ delta يستخدم cashBalance من closure قديم فيسبب ارتداداً مرئياً ثم يُلغى بـ newCash
      const hasAbsoluteCash = typeof newCash === 'number';
      const hasAbsoluteWallets =
        newWallets && typeof newWallets === 'object' && !Array.isArray(newWallets);
      const skipDeltaForBalances = hasAbsoluteCash && hasAbsoluteWallets;

      // Handle Delta Update (Preferred for optimistic updates to avoid zeroing)
      if (delta && !skipDeltaForBalances) {
        const { amount, type, walletId, commission, totalDeducted } = delta;
        const amt = Number(amount || 0);
        const comm = Number(commission || 0);
        const totalDed = Number(totalDeducted || (amt + comm));

        let change = 0;
        if (type === 'withdraw') {
          change = -amt + comm;
        } else if (type === 'send' || type === 'transfer') {
          change = amt + comm;
        } else if (type === 'atm_withdraw') {
          change = amt;
        }
        const newVal = cashBalance + change;

        try {
          const cashKey = getCashBalanceKey();
          localStorage.setItem(cashKey, String(newVal));
          const now = new Date().toISOString();
          localStorage.setItem(cashKey + '_lastUpdated', now);

          // Update main userData object for sync
          if (user?.uid) {
            const localDataKey = `userData_${user.uid}`;
            const existing = localStorage.getItem(localDataKey);
            const parsed = existing ? JSON.parse(existing) : {};
            const updated = { ...parsed, cashBalance: newVal, lastUpdated: now };
            localStorage.setItem(localDataKey, JSON.stringify(updated));
            setHasLocalDataToSync(true);
          }
        } catch {}

        syncActiveDrawerBalance(newVal);
          
        if (walletId) {
              setWalletBalances(prev => {
                  const currentVal = Number(prev[walletId] || 0);
                  let change = 0;
                  if (type === 'withdraw') {
                      // Merchant receives e-money
                      change = amt;
                  } else if (type === 'send' || type === 'transfer') {
                      // Merchant sends e-money
                      change = -amt;
                  } else if (type === 'atm_withdraw') {
                      // Merchant sends e-money (Amount + Commission)
                      change = -totalDed;
                  }
                  const newVal = currentVal + change;
                  const updatedWallets = { ...prev, [walletId]: newVal };
                  
                  try {
                    const walletKey = getWalletBalancesKey();
                    localStorage.setItem(walletKey, JSON.stringify(updatedWallets));
                    const now = new Date().toISOString();
                    localStorage.setItem(walletKey + '_lastUpdated', now);

                    // Update main userData object for sync
                    if (user?.uid) {
                      const localDataKey = `userData_${user.uid}`;
                      const existing = localStorage.getItem(localDataKey);
                      const parsed = existing ? JSON.parse(existing) : {};
                      const updated = { ...parsed, walletBalances: updatedWallets, lastUpdated: now };
                      localStorage.setItem(localDataKey, JSON.stringify(updated));
                      setHasLocalDataToSync(true);
                    }
                  } catch {}
                  return updatedWallets;
              });
          }
      }

      if (typeof newCash === 'number') {
        syncActiveDrawerBalance(newCash);
        try {
          const cashKey = getCashBalanceKey();
          localStorage.setItem(cashKey, String(newCash));
          const now = new Date().toISOString();
          localStorage.setItem(cashKey + '_lastUpdated', now);

          // Update main userData object for sync
          if (user?.uid) {
            const localDataKey = `userData_${user.uid}`;
            const existing = localStorage.getItem(localDataKey);
            const parsed = existing ? JSON.parse(existing) : {};
            const updated = { ...parsed, cashBalance: newCash, lastUpdated: now };
            localStorage.setItem(localDataKey, JSON.stringify(updated));
            setHasLocalDataToSync(true);
          }
        } catch {}
      }
      
      if (newWallets && typeof newWallets === 'object') {
        setWalletBalances(newWallets);
        try {
          const walletKey = getWalletBalancesKey();
          localStorage.setItem(walletKey, JSON.stringify(newWallets));
          const now = new Date().toISOString();
          localStorage.setItem(walletKey + '_lastUpdated', now);

          // Update main userData object for sync
          if (user?.uid) {
            const localDataKey = `userData_${user.uid}`;
            const existing = localStorage.getItem(localDataKey);
            const parsed = existing ? JSON.parse(existing) : {};
            const updated = { ...parsed, walletBalances: newWallets, lastUpdated: now };
            localStorage.setItem(localDataKey, JSON.stringify(updated));
            setHasLocalDataToSync(true);
          }
        } catch {}
      }

      if (skipDeltaForBalances && user?.uid) {
        try {
          const sidGuard = shopIdCtx || profile?.shopId || 'main';
          const ts = new Date().toISOString();
          localStorage.setItem(
            `balance_guard_${user.uid}_${sidGuard}`,
            JSON.stringify({
              ts,
              cashBalance: Math.round(Number(newCash)),
              walletBalances: newWallets as Record<string, number>,
            })
          );
        } catch {
          /* ignore */
        }
      }

      if (limitUpdate && limitUpdate.walletId === selectedWallet) {
          setSelectedWalletLimits(prev => {
              if (!prev) return prev;
              const amount = Number(limitUpdate.amount || 0);
              const isTransfer = limitUpdate.type === 'transfer';
              const newLimits = { ...prev };
              if (isTransfer) {
                  newLimits.dailyTransferUsed = (newLimits.dailyTransferUsed || 0) + amount;
                  newLimits.monthlyTransferUsed = (newLimits.monthlyTransferUsed || 0) + amount;
              } else {
                  newLimits.dailyWithdrawUsed = (newLimits.dailyWithdrawUsed || 0) + amount;
                  newLimits.monthlyWithdrawUsed = (newLimits.monthlyWithdrawUsed || 0) + amount;
              }
              return newLimits;
          });
      }
      
      if (newTransaction) {
        // Fuzzy deduplication for machine withdrawals to prevent double receipts
        const isMachineWithdrawal = (newTransaction.type === 'machine_withdrawal' || (newTransaction as any).txnType === 'machine_withdrawal');
        const currentTransactions = transactionsRef.current || [];
        
        // Check for fuzzy duplicates (same amount, same machine, within 1 minute)
        if (isMachineWithdrawal) {
             const duplicate = currentTransactions.find(t => {
                const tType = (t as any).type || (t as any).txnType;
                if (tType !== 'machine_withdrawal') return false;
                
                const sameAmount = Number((t as any).amount) === Number((newTransaction as any).amount);
                const sameSender = (t as any).senderName === (newTransaction as any).senderName;
                
                const tTime = new Date((t as any).createdAt).getTime();
                const newTime = new Date((newTransaction as any).createdAt || Date.now()).getTime();
                const timeDiff = Math.abs(newTime - tTime);
                
                return sameAmount && sameSender && timeDiff < 60000;
             });

             if (duplicate) {
                 console.log('Skipping duplicate machine withdrawal event (fuzzy match):', newTransaction);
                 return;
             }
        }

        // عام: تجنّب تكرار إيصالات الاستلام التلقائي لنفس العملية (سحب/إرسال/استلام)
        try {
          const txType = (newTransaction as any).type || (newTransaction as any).txnType;
          const isCashLike =
            txType === 'withdraw' ||
            txType === 'send' ||
            txType === 'receive' ||
            txType === 'cash_addition';
          if (isCashLike) {
            const amtNew = Number((newTransaction as any).amount || 0);
            const phoneKey = String(
              (newTransaction as any).senderNumber ||
              (newTransaction as any).senderPhone ||
              (newTransaction as any).receiverNumber ||
              (newTransaction as any).receiverPhone ||
              ''
            );
            const newTime = new Date((newTransaction as any).createdAt || Date.now()).getTime();

            const fuzzyDup = currentTransactions.find((t: any) => {
              const tType = t.type || t.txnType;
              if (tType !== txType) return false;
              const tAmt = Number(t.amount || 0);
              const tPhone = String(
                t.senderNumber ||
                t.senderPhone ||
                t.receiverNumber ||
                t.receiverPhone ||
                ''
              );
              if (tAmt !== amtNew || !phoneKey || tPhone !== phoneKey) return false;
              const tTime = new Date(t.createdAt || Date.now()).getTime();
              const diff = Math.abs(newTime - tTime);
              // اعتبرها مكررة لو في خلال دقيقة واحدة
              return diff < 60000;
            });

            if (fuzzyDup) {
              console.log('Skipping duplicate SMS/auto-receive transaction (fuzzy match):', newTransaction);
              return;
            }
          }
        } catch {}

        // عام: تجنب ظهور \"إيصال السيرفر\" لنفس العملية إذا كان هناك إيصال محلي بنفس المرجع/المعرف
        try {
          const refA = String((newTransaction as any).reference || (newTransaction as any).transactionId || (newTransaction as any).id || '');
          if (refA) {
            const dup = currentTransactions.find(t => {
              const r = String((t as any).reference || (t as any).transactionId || (t as any).id || '');
              return r && r === refA;
            });
            if (dup) {
              console.log('Skipping server transaction because a local receipt already exists for ref/id:', refA);
              return;
            }
          }
        } catch {}

        // Add to local buffer to persist through refetches
        try {
            if (localTransactionsBuffer.current) {
                if (!localTransactionsBuffer.current.some((t: any) => t.id === newTransaction.id)) {
                    localTransactionsBuffer.current.push(newTransaction);
                }
            }
        } catch {}

        setTransactions((prev: any[]) => {
          if (prev.some(t => t.id === newTransaction.id)) {
            return prev;
          }
          return [newTransaction, ...prev];
        });
        
        toast({
          title: "تم تسجيل عملية خارجية",
          description: "تم تحديث الأرصدة والسجلات بنجاح",
        });
      }
    };

    window.addEventListener('dashboard:external-update', handleExternalUpdate);
    return () => window.removeEventListener('dashboard:external-update', handleExternalUpdate);
  }, [selectedWallet]);


  // بحث عن المحفظة برقمها داخل قائمة الاختيار
