  // حذف الإيصال مع عكس التأثيرات على الحدود والأرصدة والتقارير
  const handleDeleteReceipt = async (transactionId: string) => {
    try {
      const tx = transactions.find(t => t.id === transactionId);
      if (!tx || !user) return;
      const idStr = String(transactionId);
      const refStr = String((tx as any)?.transactionId || (tx as any)?.reference || '');
      const alreadyApplied = deletedEffectsAppliedRef.current.has(idStr) || (refStr && deletedEffectsAppliedRef.current.has(refStr));

      // منع عودة الإيصال من كاش React Query / الدمج مع القائمة المحلية (نفس منطق handleDeleteTransaction)
      try {
        const sid = shopIdCtx || profile?.shopId || 'main';
        const extraIds = [
          idStr,
          String((tx as any)?.transactionId || ''),
          String((tx as any)?.reference || (tx as any)?.transactionReference || (tx as any)?.receipt?.reference || ''),
        ].filter((x) => String(x).trim() !== '');
        addPermanentDeletedIdsToLS(user.uid, sid, extraIds);
        stripTransactionFromTransactionsLocalStorageKeys(user.uid, sid, transactionId);
        const delKey = getTransactionKey(tx);
        localTransactionsBuffer.current = (localTransactionsBuffer.current || []).filter(
          (b: any) => getTransactionKey(b) !== delKey && String(b?.id || '') !== idStr
        );
        setPermanentDeletedSyncTick((t) => t + 1);
        queryClientHook.invalidateQueries({ queryKey: ['recentTransactions', user.uid] });
        queryClientHook.invalidateQueries({ queryKey: ['userTransactions', user.uid] });
      } catch {
        /* ignore */
      }

      // تنظيف localReceipts فوراً قبل أي await — وإلا يعيد effect الدمج الإيصال من التخزين المحلي
      try {
        if (user?.uid) {
          userDataService.removeLocalReceiptById(user.uid, transactionId);
          const refPurge = String((tx as any)?.reference || (tx as any)?.transactionReference || '').trim();
          if (refPurge) userDataService.removeLocalReceiptByRef(user.uid, refPurge);
          setLocalReceiptsRevision((r) => r + 1);
        }
      } catch {
        /* ignore */
      }

      // إزالة المعاملة نهائيًا من القائمة الحالية فقط (يتم الحذف من Firestore أدناه)
      const updatedTransactions = transactions.filter(t => t.id !== transactionId);
      setTransactions(updatedTransactions);

      // حذف نهائي من Firebase لضمان عدم العودة
      try {
        await userDataService.removeUserTransaction(user.uid, transactionId);
        await auditLogService.permanentlyDeleteTransaction(transactionId, user.uid);
      } catch (e) {
        console.warn('تعذر الحذف النهائي من قواعد البيانات أثناء حذف الإيصال:', e);
      }
      // تطبيق تأثيرات الحذف مرة واحدة فقط (أرصدة/حدود)
      if (!alreadyApplied) {
        deletedEffectsAppliedRef.current.add(idStr);
        if (refStr) deletedEffectsAppliedRef.current.add(refStr);
        await applyLocalDeleteEffects(tx);
      }

      toast({
        title: 'تم الحذف نهائيًا',
        description: 'تم حذف الإيصال نهائيًا وعكس تأثيراته على الأرصدة والحدود والتقارير.',
      });

      setIsReceiptOpen(false);
    } catch (err) {
      console.error('خطأ أثناء حذف الإيصال:', err);
      toast({
        title: 'خطأ في حذف الإيصال',
        description: 'حدث خطأ غير متوقع أثناء الحذف.',
        variant: 'destructive',
      });
    }
  };

  // زر "تصحيح آخر عملية" من الإعدادات: يحذف آخر إيصال في القائمة ويعكس تأثيره
  useEffect(() => {
    const handler = () => {
      try {
        const lastTx = transactions[0];
        if (!lastTx) {
          toast({
            title: 'لا توجد عمليات متاحة',
            description: 'لا يوجد إيصال أخير يمكن تصحيحه حالياً.',
          });
          return;
        }
        // نحاول أولاً استعادة اللقطة الكاملة إن وُجدت لضمان عودة الأرصدة كما كانت
        const snapshot = lastTxSnapshotRef.current || (() => {
          try {
            if (user?.uid) {
              const raw = localStorage.getItem(`undo_last_tx_snapshot_${user.uid}`);
              return raw ? JSON.parse(raw) : null;
            }
          } catch {}
          return null;
        })();

        if (snapshot && (snapshot.txId === lastTx.id || snapshot.txReference === (lastTx as any).reference || snapshot.txReference === (lastTx as any).transactionId)) {
          // استعادة الأرصدة من اللقطة
          const restoredCash = Number(snapshot.cashBalance || 0);
          const restoredWallets = snapshot.walletBalances || {};
          setCashBalance(restoredCash);
          setWalletBalances(restoredWallets);
          if (snapshot.selectedWalletLimits) {
            setSelectedWalletLimits(snapshot.selectedWalletLimits);
          }

          // حفظ الأرصدة المستعادة في التخزين المحلي أيضاً
          try {
            const cashKey = getCashBalanceKey();
            const walletKey = getWalletBalancesKey();
            const nowIso = new Date().toISOString();
            localStorage.setItem(cashKey, String(restoredCash));
            localStorage.setItem(cashKey + '_lastUpdated', nowIso);
            localStorage.setItem(walletKey, JSON.stringify(restoredWallets));
            localStorage.setItem(walletKey + '_lastUpdated', nowIso);
            if (user?.uid) {
              const localDataKey = `userData_${user.uid}`;
              localStorage.setItem(localDataKey, JSON.stringify({
                cashBalance: restoredCash,
                walletBalances: restoredWallets,
                lastUpdated: nowIso,
              }));
            }
          } catch {}

          // إزالة المعاملة من القائمة وحذفها من السحابة قدر الإمكان
          setTransactions(prev => prev.filter(t => t.id !== lastTx.id));
          (async () => {
            try {
              if (user?.uid) {
                await userDataService.removeUserTransaction(user.uid, lastTx.id);
                try { await auditLogService.permanentlyDeleteTransaction(lastTx.id, user.uid); } catch {}
              }
            } catch (e) {
              console.warn('Failed to delete last transaction while undoing:', e);
            }
          })();
        } else {
          // في حال عدم توفر لقطة موثوقة نرجع لسلوك الحذف التقليدي
          handleDeleteReceipt(lastTx.id);
        }
      } catch (e) {
        console.error('Failed to undo last transaction:', e);
        toast({
          title: 'تعذر تصحيح آخر عملية',
          description: 'حدث خطأ أثناء محاولة إلغاء آخر عملية.',
          variant: 'destructive',
        });
      }
    };
    window.addEventListener('dashboard:undo-last-transaction', handler);
    return () => window.removeEventListener('dashboard:undo-last-transaction', handler);
  }, [transactions, toast, handleDeleteReceipt, user?.uid]);

  // إكمال الإيصال: تحديث حالة المعاملة إلى مكتملة
  const handleCompleteReceipt = async (transactionId: string) => {
    try {
      const tx = transactions.find(t => t.id === transactionId);
      if (!tx || !user) return;

      // حد باقة الزيرو: 5 تأكيدات يوميًا للتحويل/السحب
      try {
        const plan = userSubscription?.planType;
        if (plan === SubscriptionPlan.ZERO) {
          const { dailyOperationCountService } = await import('@/utils/dailyOperationCountService');
          const opType = (tx as any).type === 'send' ? 'transfer' : 'withdraw';
          const res = await dailyOperationCountService.checkAndIncrement(user.uid, opType, 5);
          if (!res.allowed) {
            toast({
              title: 'تم بلوغ حد باقة الزيرو',
              description: 'مسموح بحد أقصى 5 تأكيدات يوميًا للتحويل/السحب. جرّب غدًا أو قم بالترقية.',
              variant: 'destructive',
            });
            return;
          }
        } else if (plan === SubscriptionPlan.TAHWEELA) {
          const { dailyOperationCountService } = await import('@/utils/dailyOperationCountService');
          const opType = (tx as any).type === 'send' ? 'transfer' : 'withdraw';
          const res = await dailyOperationCountService.checkAndIncrementCombined(user.uid, opType, 40);
          if (!res.allowed) {
            toast({
              title: 'تم بلوغ حد باقة تحويله',
              description: 'هذه الباقة تسمح بحد أقصى 40 عملية تحويل/سحب يومياً.',
              variant: 'destructive',
            });
            return;
          }
        }
      } catch (limitErr) {
        console.warn('تعذر التحقق من حد التأكيد اليومي:', limitErr);
      }

      await updateDoc(doc(db, 'userTransactions', transactionId), {
        status: 'completed',
        confirmedAt: new Date()
      });

      setTransactions(prev => prev.map(t => t.id === transactionId ? { ...t, status: 'completed' } : t));

      toast({
        title: 'تم الإكمال',
        description: 'تم وسم المعاملة كمكتملة.'
      });

      setIsReceiptOpen(false);
    } catch (err) {
      console.error('خطأ أثناء إكمال الإيصال:', err);
      toast({
        title: 'فشل الإكمال',
        description: 'حدث خطأ غير متوقع أثناء تحديث الحالة.',
        variant: 'destructive'
      });
    }
  };

