  // استماع فوري لتغيرات حالة المستخدم والاشتراك (Real-time Listener)
  useEffect(() => {
    if (!user?.uid) return;

    const unsubscribe = onSnapshot(
      doc(db, 'users', user.uid),
      async (snapshot) => {
        if (snapshot.exists()) {
          const userData = snapshot.data();
          const trialValidity = await FreeTrialService.checkTrialValidity(user.uid);
          const isOnTrial = trialValidity.isValid && !trialValidity.isExpired;
          const allowed = isDashboardAccessAllowed(userData, trialValidity);

          // تحديث بيانات الاشتراك إذا وجدت
          if (userData.subscription) {
            setUserSubscription(userData.subscription);
          }

          // Update branch package info (real-time)
          setBranchPackage(userData.branchPackage || null);

          setIsUserActive(allowed);
          setIsOnFreeTrial(isOnTrial);
          setFreeTrialHoursRemaining(trialValidity.hoursRemaining);
          setHasUsedFreeTrial(trialValidity.hasUsedTrial);

          // نافذة التفعيل/التحويل لصفحة الانتظار فقط إذا لا يوجد وصول (حساب أو اشتراك ساري أو تجربة)
          const shouldShowModal = !allowed;
          setShowActivationModal(shouldShowModal);

          if (shouldShowModal) {
            console.log('⛔ User not active, redirecting to pending approval...');
            navigate('/user/pending-approval', { replace: true });
          }

          console.log('🔄 تحديث فوري لحالة المستخدم (Real-time):', {
            docIsActive: userData.isActive === true,
            isOnTrial,
            allowed,
            plan: userData.subscription?.planType,
            showModal: shouldShowModal,
            fromCache: snapshot.metadata.fromCache,
          });
        } else {
          setIsUserActive(false);
          setShowActivationModal(true);
        }
      },
      (err) => {
        console.warn('مستمع users/الاشتراك:', err);
      }
    );

    return () => unsubscribe();
  }, [user?.uid, navigate]);

  // دالة لإعادة فحص حالة المستخدم
