    // تطبيق التصفير التلقائي للحدود في اليوم الأول من كل شهر
    const autoResetLimits = async () => {
      try {
        if (!user?.uid) return;
        // تصفير حدود كل محافظ للمستخدم الحالي باستخدام معرف المحفظة الصحيح
        const wallets = await merchantWalletService.getByMerchantId(user.uid);
        await Promise.all(
          wallets.map((w: any) => walletLimitsService.autoResetLimitsIfNeeded(w.id))
        );
      } catch (error) {
        console.error('خطأ في التصفير التلقائي للحدود:', error);
      }
    };

    // تطبيق الأرشفة قبل التصفير التلقائي للتقارير
    const autoResetReports = async () => {
      try {
        // مزامنة بيانات التقارير من Firebase إلى التخزين المحلي قبل أي حسابات
        await reportsService.syncReportsDataFromFirebase(user?.uid);
        const data = reportsService.getReportsData(user?.uid);
        const shouldArchiveDaily = data.lastDailyResetDate ? reportsService.shouldResetDailyReports(data.lastDailyResetDate) : false;
        if (shouldArchiveDaily && user?.uid && data.lastDailyResetDate) {
          const dayDate = new Date(data.lastDailyResetDate);
          const baseDateStr = dayDate.toDateString();
          // حصر معاملات ذلك اليوم فقط دون فلترة الإخفاء — الأرشيف يجب أن يحتفظ بإحصائيات اليوم كاملة
          const dayTransactions = transactions.filter(tx =>
            new Date(tx.createdAt).toDateString() === baseDateStr && tx.status === 'completed'
          );
          const totalTransactions = dayTransactions.length;
          const totalAmount = dayTransactions.reduce((sum, tx) => sum + tx.amount, 0);
          const totalWithdrawn = dayTransactions
            .filter(isWithdrawTx)
            .reduce((sum, tx) => {
              const amount = (tx as any).withdrawnAmount !== undefined ? (tx as any).withdrawnAmount : tx.amount;
              return sum + amount;
            }, 0);
          const totalSent = dayTransactions
            .filter(isSendTx)
            .reduce((sum, tx) => {
              const amount = (tx as any).sentAmount !== undefined ? (tx as any).sentAmount : tx.amount;
              return sum + amount;
            }, 0);
          const profit = dayTransactions.reduce((sum, tx) => sum + reportsService.calculateTransactionProfit(tx), 0);

          const reportDateStr = new Date(dayDate).toISOString().slice(0, 10);
          await dailyReportsArchiveService.add({
            userId: user.uid,
            reportDate: reportDateStr,
            totalTransactions,
            totalAmount: Math.round(totalAmount),
            totalWithdrawn: Math.round(totalWithdrawn),
            totalSent: Math.round(totalSent),
            profit: Math.round(profit),
            walletId: null
          });
        }

        const resetResult = reportsService.autoResetReportsIfNeeded(user?.uid);
        if (resetResult.dailyReset || resetResult.monthlyReset) {
          console.log('تم التصفير التلقائي:', resetResult);
          // لا حاجة لإعادة تحميل المعاملات لأن النظام الجديد يخفي المعاملات بدلاً من حذفها
        }
      } catch (error) {
        console.error('خطأ في التصفير التلقائي للتقارير:', error);
      }
    };

    // تنظيف تلقائي لقاعدة البيانات يوم 1 من كل شهر (حذف إيصالات الأشهر السابقة من Firebase فقط)
    const autoMonthlyDbCleanup = async () => {
      try {
        if (!user?.uid) return;
        const today = new Date();
        if (today.getDate() !== 1) return; // يعمل فقط يوم 1
        const tag = `${today.getFullYear()}-${today.getMonth() + 1}`;
        const key = `lastMonthlyDbCleanup:${user.uid}`;
        const last = localStorage.getItem(key);
        if (last === tag) return; // تم التنفيذ بالفعل هذا الشهر

        const monthStart = new Date(today.getFullYear(), today.getMonth(), 1, 0, 0, 0, 0);
        const toJsDate = (v: any) => (v instanceof Date) ? v : (typeof v?.toDate === 'function') ? v.toDate() : new Date(String(v));

        // userTransactions
        let utDocs: any[] = [];
        try {
          const q1 = fsQuery(
            collection(db, 'userTransactions'),
            where('userId', '==', user.uid),
            where('createdAt', '<', monthStart)
          );
          const snap1 = await getDocs(q1);
          utDocs = snap1.docs;
        } catch {
          const q1fb = fsQuery(
            collection(db, 'userTransactions'),
            where('userId', '==', user.uid)
          );
          const snap1fb = await getDocs(q1fb);
          utDocs = snap1fb.docs.filter(d => toJsDate(d.data()?.createdAt) < monthStart);
        }
        await Promise.allSettled(utDocs.map(d => deleteDoc(d.ref)));

        // transactions (المجموعة العامة)
        let gDocs: any[] = [];
        try {
          const q2 = fsQuery(
            collection(db, 'transactions'),
            where('userId', '==', user.uid),
            where('createdAt', '<', monthStart)
          );
          const snap2 = await getDocs(q2);
          gDocs = snap2.docs;
        } catch {
          const q2fb = fsQuery(
            collection(db, 'transactions'),
            where('userId', '==', user.uid)
          );
          const snap2fb = await getDocs(q2fb);
          gDocs = snap2fb.docs.filter(d => toJsDate(d.data()?.createdAt) < monthStart);
        }
        await Promise.allSettled(gDocs.map(d => deleteDoc(d.ref)));

        try { localStorage.setItem(key, tag); } catch { }
        console.log('✅ تم تنظيف قاعدة البيانات شهريًا (Firebase فقط):', {
          userTransactionsDeleted: utDocs.length,
          globalTransactionsDeleted: gDocs.length,
          monthStart
        });
      } catch (e) {
        console.error('فشل التنظيف الشهري التلقائي لقاعدة البيانات:', e);
      }
    };

    // جلب بيانات الاشتراك
    fetchSubscriptionData();

    // تحميل الديون
    loadDebtsFromStorage();
    // تحميل العملاء
    loadCustomersFromStorage();

