  // استماع للتحديثات اللحظية للمعاملات (لحل مشكلة عدم ظهور الإيصالات المسجلة من الموبايل)
  useEffect(() => {
    if (!user?.uid) return;
    
    // اشتراك في آخر 30 معاملة لتحديث القائمة فورياً
    const unsubscribe = userDataService.subscribeToUserTransactions(user.uid, (newRawTransactions) => {
       if (!newRawTransactions || newRawTransactions.length === 0) return;

       // تحويل البيانات بنفس منطق loadUserData
       const processed = newRawTransactions.map((tx: any) => ({
            ...tx,
            createdAt: new Date(tx.createdAt),
            senderPhone: tx.senderMsisdn || tx.senderPhone || '',
            receiverPhone: tx.receiverMsisdn || tx.receiverPhone || '',
            type: tx.txnType === 'send' ? 'send' :
              tx.txnType === 'receive' ? 'withdraw' :
                tx.type || 'withdraw',
            status: tx.status === 'confirmed' ? 'completed' : tx.status || 'completed'
       }));

       setTransactions(prev => {
          // دمج المعاملات الجديدة مع القديمة مع إزالة التكرار
          const combined = [...processed, ...prev];
          const seen = new Set<string>();
          const distinct: any[] = [];
          
          for (const t of combined) {
             const key = getTransactionKey(t);
             if (!seen.has(key)) {
                seen.add(key);
                distinct.push(t);
             }
          }
          
          // إعادة الفرز زمنياً (الأحدث أولاً)
          return distinct.sort((a: any, b: any) => {
             const ta = a.createdAt instanceof Date ? a.createdAt.getTime() : new Date(a.createdAt).getTime();
             const tb = b.createdAt instanceof Date ? b.createdAt.getTime() : new Date(b.createdAt).getTime();
             return tb - ta;
          });
       });
    }, 30);

    return () => unsubscribe();
  }, [user?.uid]);

