                  // الربح (العمولة) من المعاملة المرتبطة — المبلغ المتبقي = المبلغ المسحوب - العمولة - المدفوع
                  const profitFromLinked = (transactions || []).filter((t: any) => String(t?.linkedDebtId || '') === String(selectedDebt.id))
                    .reduce((sum: number, t: any) => sum + Math.max(0, Number(t?.commission || 0)), 0);
