                    const isFullyPaid = newPaidTotal >= baseAmt;
                    return {
                      ...debt,
                      amount: baseAmt,
                      paidAmount: isFullyPaid ? baseAmt : newPaidTotal,
                      status: 'paid' as const,
                      partialPayments: [
                        ...(debt.partialPayments || []),
                        ...(payAmount > 0 ? [{ amount: payAmount, paidAt: new Date() }] : [])
                      ]
                    };
