/**
 * دوال التحقق من صحة أرقام المحافظ المصرية
 * Egyptian wallet number validation utilities
 */

// أنواع مزودي الخدمة المدعومة
export type WalletProvider = 'vodafone' | 'orange' | 'etisalat' | 'we';

// أكواد الأخطاء المحتملة
export type ValidationErrorCode = 
  | 'INVALID_MSISDN'
  | 'PROVIDER_MISMATCH'
  | 'ALREADY_EXISTS'
  | 'UNAUTHENTICATED'
  | 'RLS_DENIED'
  | 'UNKNOWN';

// نتيجة التحقق
export interface ValidationResult {
  isValid: boolean;
  normalizedMsisdn?: string;
  errorCode?: ValidationErrorCode;
  errorMessage?: string;
}

// مطابقة مقدمات الأرقام مع مزودي الخدمة
const PROVIDER_PREFIXES: Record<WalletProvider, string> = {
  vodafone: '010',
  orange: '012',
  etisalat: '011',
  we: '015'
};

/**
 * تطبيع رقم MSISDN المصري وتحويله لصيغة E.164
 * @param rawMsisdn الرقم الخام كما أدخله المستخدم
 * @returns الرقم المطبع بصيغة E.164 أو null إذا كان غير صالح
 */
export function normalizeEgyptianMsisdn(rawMsisdn: string): string | null {
  if (!rawMsisdn) return null;

  // إزالة المسافات والشرطات والأحرف غير الرقمية
  let cleaned = rawMsisdn.replace(/[^0-9٠-٩]/g, '');
  
  // تحويل الأرقام العربية إلى إنجليزية
  cleaned = cleaned.replace(/[٠-٩]/g, (match) => {
    const arabicDigits = '٠١٢٣٤٥٦٧٨٩';
    const englishDigits = '0123456789';
    return englishDigits[arabicDigits.indexOf(match)];
  });

  // التحقق من أن الرقم 11 رقم ويبدأ بـ 01
  if (cleaned.length !== 11 || !cleaned.startsWith('01')) {
    return null;
  }

  // تحويل لصيغة E.164: 01XXXXXXXXX → +201XXXXXXXXX
  return `+20${cleaned.substring(1)}`;
}

/**
 * التحقق من مطابقة مزود الخدمة مع مقدمة الرقم
 * @param provider مزود الخدمة المختار
 * @param normalizedMsisdn الرقم المطبع بصيغة E.164
 * @returns true إذا كان المزود يتطابق مع مقدمة الرقم
 */
export function validateProviderMatch(provider: WalletProvider, normalizedMsisdn: string): boolean {
  if (!normalizedMsisdn.startsWith('+201')) return false;
  
  // استخراج المقدمة من الرقم المطبع (بعد +201)
  const prefix = normalizedMsisdn.substring(3, 6); // +201XXXXXXXXX → 0XX
  const expectedPrefix = PROVIDER_PREFIXES[provider];
  
  return prefix === expectedPrefix;
}

/**
 * التحقق الشامل من صحة رقم المحفظة
 * @param provider مزود الخدمة
 * @param rawMsisdn الرقم الخام
 * @returns نتيجة التحقق مع الرقم المطبع أو رسالة الخطأ
 */
export function validateWalletNumber(provider: WalletProvider, rawMsisdn: string): ValidationResult {
  // تطبيع الرقم
  const normalizedMsisdn = normalizeEgyptianMsisdn(rawMsisdn);
  
  if (!normalizedMsisdn) {
    return {
      isValid: false,
      errorCode: 'INVALID_MSISDN',
      errorMessage: 'رقم المحفظة غير صالح. اكتب 11 رقم يبدأ بـ 01'
    };
  }

  // التحقق من مطابقة المزود
  if (!validateProviderMatch(provider, normalizedMsisdn)) {
    const expectedPrefix = PROVIDER_PREFIXES[provider];
    return {
      isValid: false,
      errorCode: 'PROVIDER_MISMATCH',
      errorMessage: `مقدم الخدمة ${getProviderDisplayName(provider)} يتطلب أرقام تبدأ بـ ${expectedPrefix}`
    };
  }

  return {
    isValid: true,
    normalizedMsisdn
  };
}

/**
 * الحصول على الاسم المعروض لمزود الخدمة
 * @param provider مزود الخدمة
 * @returns الاسم المعروض بالعربية
 */
export function getProviderDisplayName(provider: WalletProvider): string {
  const names: Record<WalletProvider, string> = {
    vodafone: 'فودافون كاش',
    orange: 'أورانج كاش',
    etisalat: 'اتصالات كاش',
    we: 'وي كاش'
  };
  return names[provider];
}

/**
 * التحقق السريع من صحة الرقم على الواجهة
 * @param msisdن الرقم المدخل
 * @returns true إذا كان الرقم يبدو صالحاً
 */
export function quickValidateMsisdn(msisdn: string): boolean {
  if (!msisdn) return false;
  
  // إزالة المسافات والشرطات
  const cleaned = msisdn.replace(/[^0-9٠-٩]/g, '');
  
  // تحويل الأرقام العربية
  const normalized = cleaned.replace(/[٠-٩]/g, (match) => {
    const arabicDigits = '٠١٢٣٤٥٦٧٨٩';
    const englishDigits = '0123456789';
    return englishDigits[arabicDigits.indexOf(match)];
  });

  // التحقق من النمط: 11 رقم يبدأ بـ 01
  return /^01[0-9]{9}$/.test(normalized);
}

/**
 * التحقق الصارم: 11 رقم ويبدأ فقط بـ 010 أو 011 أو 012 أو 015
 * يقبل أيضاً الأرقام العربية ويحذف المسافات/الشرطات
 */
export function strictValidateMsisdn(msisdn: string): boolean {
  if (!msisdn) return false;
  const cleaned = msisdn.replace(/[^0-9٠-٩]/g, '');
  const normalized = cleaned.replace(/[٠-٩]/g, (match) => {
    const arabicDigits = '٠١٢٣٤٥٦٧٨٩';
    const englishDigits = '0123456789';
    return englishDigits[arabicDigits.indexOf(match)];
  });
  return /^(010|011|012|015)[0-9]{8}$/.test(normalized);
}

/**
 * الحصول على رسالة خطأ مفهومة للمستخدم
 * @param errorCode كود الخطأ
 * @returns رسالة الخطأ بالعربية
 */
export function getErrorMessage(errorCode: ValidationErrorCode): string {
  const messages: Record<ValidationErrorCode, string> = {
    INVALID_MSISDN: 'رقم المحفظة غير صالح. اكتب 11 رقم يبدأ بـ 01',
    PROVIDER_MISMATCH: 'مقدم الخدمة لا يتطابق مع مقدمة الرقم',
    ALREADY_EXISTS: 'المحفظة مضافة من قبل',
    UNAUTHENTICATED: 'يجب تسجيل الدخول أولاً',
    RLS_DENIED: 'حسابك غير مصرح له بإضافة هذه المحفظة',
    UNKNOWN: 'حدث خطأ غير متوقع أثناء إضافة المحفظة'
  };
  return messages[errorCode];
}