import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Eye, EyeOff, Lock, AlertCircle } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { ProfitService } from '@/utils/profitService';
import { MasterPinService } from '@/utils/masterPinService';
import { useEffect } from 'react';

interface ProfitPinDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
  userId?: string;
}

export function ProfitPinDialog({ 
  open, 
  onOpenChange, 
  onSuccess, 
  userId 
}: ProfitPinDialogProps) {
  const [pin, setPin] = useState('');
  const [confirmPin, setConfirmPin] = useState('');
  const [showPin, setShowPin] = useState(false);
  const [showConfirmPin, setShowConfirmPin] = useState(false);
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [hasExistingPin, setHasExistingPin] = useState(false);
  const { toast } = useToast();
  const formRef = React.useRef<HTMLFormElement>(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      const has = await MasterPinService.hasMasterPin(userId);
      if (mounted) setHasExistingPin(has);
    })();
    return () => {
      mounted = false;
    };
  }, [userId, open]);

  const handleClose = () => {
    setPin('');
    setConfirmPin('');
    setError('');
    setShowPin(false);
    setShowConfirmPin(false);
    onOpenChange(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      if (hasExistingPin) {
        // التحقق من الرقم السري الرئيسي
        const ok = await MasterPinService.verifyMasterPin(pin, userId);
        if (!ok) {
          setError('الرقم السري غير صحيح');
          setIsLoading(false);
          return;
        }
      } else {
        // إنشاء رقم سري رئيسي جديد
        if (pin.length < 4) {
          setError('يجب أن يكون الرقم السري 4 أرقام على الأقل');
          setIsLoading(false);
          return;
        }

        if (pin !== confirmPin) {
          setError('الرقم السري غير متطابق');
          setIsLoading(false);
          return;
        }

        const created = await MasterPinService.createMasterPin(pin, userId);
        if (!created) {
          setError('تعذر إنشاء الرقم السري الرئيسي');
          setIsLoading(false);
          return;
        }
      }

      toast({
        title: "نجح العملية",
        description: hasExistingPin 
          ? "تم التحقق من الرقم السري الرئيسي بنجاح" 
          : "تم إنشاء الرقم السري الرئيسي بنجاح",
      });

      onSuccess();
      handleClose();
    } catch (error) {
      setError('حدث خطأ أثناء معالجة الرقم السري');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md" dir="rtl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2 text-lg font-semibold">
            <Lock className="h-5 w-5 text-green-600" />
            {hasExistingPin ? 'أدخل الرقم السري الرئيسي' : 'إنشاء الرقم السري الرئيسي'}
          </DialogTitle>
        </DialogHeader>

        <form ref={formRef} onSubmit={handleSubmit} className="space-y-4">
          <div className="text-sm text-gray-600 bg-blue-50 p-3 rounded-lg">
            {hasExistingPin 
              ? 'أدخل الرقم السري الرئيسي لعرض بيانات الأرباح'
              : 'قم بإنشاء الرقم السري الرئيسي لحماية بيانات الأرباح. يمكنك تغييره لاحقاً من إعدادات البروفيل.'
            }
          </div>

          {/* حقل الرقم السري */}
          <div className="space-y-2">
            <Label htmlFor="pin">
              {hasExistingPin ? 'الرقم السري الرئيسي' : 'الرقم السري الرئيسي الجديد'}
            </Label>
            <div className="relative">
              <Input
                id="pin"
                type={showPin ? "text" : "password"}
                value={pin}
                onChange={(e) => setPin(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); formRef.current?.requestSubmit(); } }}
                placeholder={hasExistingPin ? "أدخل الرقم السري" : "أدخل رقم سري جديد (4 أرقام على الأقل)"}
                className="pr-10"
                dir="ltr"
                autoComplete="off"
                required
              />
              <Button
                type="button"
                variant="ghost"
                size="sm"
                className="absolute left-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                onClick={() => setShowPin(!showPin)}
              >
                {showPin ? (
                  <EyeOff className="h-4 w-4" />
                ) : (
                  <Eye className="h-4 w-4" />
                )}
              </Button>
            </div>
          </div>

          {/* حقل تأكيد الرقم السري (للإنشاء الجديد فقط) */}
          {!hasExistingPin && (
            <div className="space-y-2">
              <Label htmlFor="confirmPin">تأكيد الرقم السري</Label>
              <div className="relative">
                <Input
                  id="confirmPin"
                  type={showConfirmPin ? "text" : "password"}
                  value={confirmPin}
                  onChange={(e) => setConfirmPin(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') { e.preventDefault(); formRef.current?.requestSubmit(); } }}
                  placeholder="أعد إدخال الرقم السري"
                  className="pr-10"
                  dir="ltr"
                  autoComplete="off"
                  required
                />
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="absolute left-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                  onClick={() => setShowConfirmPin(!showConfirmPin)}
                >
                  {showConfirmPin ? (
                    <EyeOff className="h-4 w-4" />
                  ) : (
                    <Eye className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </div>
          )}

          {/* رسالة الخطأ */}
          {error && (
            <div className="flex items-center gap-2 text-red-600 text-sm">
              <AlertCircle className="h-4 w-4" />
              {error}
            </div>
          )}

          {/* أزرار التحكم */}
          <div className="flex gap-2 pt-4">
            <Button
              type="submit"
              disabled={isLoading}
              className="flex-1 bg-green-600 hover:bg-green-700"
            >
              <Lock className="h-4 w-4 mr-2" />
              {isLoading 
                ? "جاري المعالجة..." 
                : hasExistingPin 
                  ? "عرض الأرباح" 
                  : "إنشاء وعرض الأرباح"
              }
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={isLoading}
            >
              إلغاء
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}