/**
 * طابور مزامنة عمليات «سحب ATM» عند عودة الاتصال / إلغاء تأجيل المزامنة.
 * الأرباح وحدود المحفظة المحلية تُحدَّث عند التأكيد أوفلاين؛ الرفع يعيد فقط مستند المستخدم + userTransactions.
 */
import { db } from '@/firebase';
import { doc, increment, serverTimestamp, writeBatch } from 'firebase/firestore';
import { isManualFirestoreHoldEffective } from '@/utils/manualFirestoreSyncHold';
import { walletDailyLimitsService } from '@/utils/walletDailyLimitsService';

export type AtmWithdrawQueuedOp = {
  t: 'atmWithdraw';
  userId: string;
  txId: string;
  amount: number;
  commission: number;
  totalCharged: number;
  netAmount: number;
  sourceWalletId: string;
  destinationType: 'cash' | 'wallet' | 'none';
  destinationWalletId: string | null;
  note: string;
  sender_msisdn: string;
  details: string;
};

export const atmWithdrawQueueKey = (uid: string) => `atmWithdraw_syncQueue_${uid}`;

export function readAtmWithdrawQueue(uid: string): AtmWithdrawQueuedOp[] {
  try {
    const raw = localStorage.getItem(atmWithdrawQueueKey(uid));
    if (!raw) return [];
    const a = JSON.parse(raw);
    return Array.isArray(a) ? a : [];
  } catch {
    return [];
  }
}

export function appendAtmWithdrawQueue(uid: string, op: AtmWithdrawQueuedOp) {
  try {
    const cur = readAtmWithdrawQueue(uid);
    cur.push(op);
    localStorage.setItem(atmWithdrawQueueKey(uid), JSON.stringify(cur));
  } catch {
    /* ignore */
  }
}

export async function flushAtmWithdrawQueue(uid: string): Promise<{ ok: number; failed: number }> {
  if (!uid || isManualFirestoreHoldEffective(uid)) return { ok: 0, failed: 0 };
  let ops: AtmWithdrawQueuedOp[];
  try {
    const raw = localStorage.getItem(atmWithdrawQueueKey(uid));
    if (!raw) return { ok: 0, failed: 0 };
    ops = JSON.parse(raw);
    if (!Array.isArray(ops) || ops.length === 0) return { ok: 0, failed: 0 };
    localStorage.setItem(atmWithdrawQueueKey(uid), '[]');
  } catch {
    return { ok: 0, failed: 0 };
  }

  const failed: AtmWithdrawQueuedOp[] = [];
  let ok = 0;

  for (const op of ops) {
    try {
      if (op.t !== 'atmWithdraw') continue;
      const userRef = doc(db, 'users', op.userId);
      const batch = writeBatch(db);
      const updates: Record<string, unknown> = {};
      updates[`walletBalances.${op.sourceWalletId}`] = increment(-op.totalCharged);
      if (op.destinationType === 'wallet' && op.destinationWalletId) {
        updates[`walletBalances.${op.destinationWalletId}`] = increment(op.netAmount);
      } else if (op.destinationType === 'cash') {
        updates.cashBalance = increment(op.netAmount);
      }
      batch.update(userRef, updates);

      const userTxRef = doc(db, 'userTransactions', op.txId);
      batch.set(userTxRef, {
        userId: op.userId,
        type: 'atm_withdraw',
        amount: op.amount,
        commission: op.commission,
        totalCharged: op.totalCharged,
        netAmount: op.netAmount,
        sourceWalletId: op.sourceWalletId,
        destinationType: op.destinationType,
        destinationWalletId: op.destinationWalletId,
        status: 'completed',
        createdAt: serverTimestamp(),
        note: op.note,
        walletId: op.sourceWalletId,
        sender_msisdn: op.sender_msisdn,
        details: op.details,
      });

      await batch.commit();

      try {
        await walletDailyLimitsService.updateUsage(op.sourceWalletId, op.amount, 'transfer', true);
      } catch (e) {
        console.warn('ATM flush: wallet limits update', e);
      }

      ok += 1;
    } catch {
      failed.push(op);
    }
  }

  if (failed.length > 0) {
    try {
      const rest = readAtmWithdrawQueue(uid);
      localStorage.setItem(atmWithdrawQueueKey(uid), JSON.stringify([...failed, ...rest]));
    } catch {
      /* ignore */
    }
  }

  return { ok, failed: failed.length };
}
